# Generated by the jhooq.com VPC Subnet Planner - https://jhooq.com/tools/vpc-subnet-planner/
RG=jhooq-rg
LOC=northeurope
VNET=jhooq-vnet

az group create --name $RG --location $LOC

az network vnet create --resource-group $RG --location $LOC --name $VNET \
  --address-prefixes 10.20.0.0/16

az network vnet subnet create --resource-group $RG --vnet-name $VNET \
  --name private --address-prefixes 10.20.0.0/20 --default-outbound false

az network vnet subnet create --resource-group $RG --vnet-name $VNET \
  --name public --address-prefixes 10.20.16.0/24

az network vnet subnet create --resource-group $RG --vnet-name $VNET \
  --name database --address-prefixes 10.20.17.0/24 --default-outbound false

